iv><div class="hh-item hh-item-ours">$87,000</div><div class="hh-item hh-item-ours">$290,000</div><div class="hh-item hh-item-ours">$8,700</div><div class="hh-item hh-item-ours">$29,000</div><div class="hh-item hh-item-ours">$87,000</div><div class="hh-item hh-item-ours">$290,000</div><div class="hh-item hh-item-ours">$8,700</div><div class="hh-item hh-item-ours">$29,000</div><div class="hh-item hh-item-ours">$87,000</div><div class="hh-item hh-item-ours">$290,000</div><div class="hh-item hh-item-ours">$8,700</div><div class="hh-item hh-item-ours">$29,000</div><div class="hh-item hh-item-ours">$87,000</div><div class="hh-item hh-item-ours">$290,000</div><div class="hh-item hh-item-ours">$8,700</div><div class="hh-item hh-item-ours">$29,000</div><div class="hh-item hh-item-ours">$87,000</div><div class="hh-item hh-item-ours">$290,000</div><div class="hh-item hh-item-ours">$8,700</div><div class="hh-item hh-item-ours">$29,000</div><div class="hh-item hh-item-ours">$87,000</div><div class="hh-item hh-item-ours">$290,000</div></div></div> </div> </div> <div class="hh-save"> <div class="hh-save-label">Extra in your pocket</div> <div class="hh-save-val" id="hh-save-val">$4,333</div> </div> <div class="hh-controls"> <button class="hh-spin-btn" id="hh-spin-btn" type="button">Spin</button> <button data-hh-idx="0" type="button">$30K</button> <button data-hh-idx="1" type="button">$100K</button> <button data-hh-idx="2" type="button">$300K</button> <button data-hh-idx="3" type="button">$1M</button> </div> <p class="hh-disclaimer">Illustrative comparison based on a 29% Hastings &amp; Hastings settlement fee vs. a typical one-third (33.33%) contingency fee. Individual results vary.</p> </div> <template data-nitro-marker-id="4df01f12d95c233363644bc8508019a3-1"></template><script>(function() {
  var data = [
    { s: 30000,   o: 10000,  h: 8700,   save: 1300  },
    { s: 100000,  o: 33333,  h: 29000,  save: 4333  },
    { s: 300000,  o: 100000, h: 87000,  save: 13000 },
    { s: 1000000, o: 333333, h: 290000, save: 43333 }
  ];
  var fmt = function(n) { return '$' + n.toLocaleString('en-US'); };
  var ITEM_H = 72;
  var REPEAT = 10;

  var widget = document.querySelector('.hh-fee-widget');
  if (!widget) return;

  // Adjust item height on mobile to match CSS
  if (window.matchMedia && window.matchMedia('(max-width: 560px)').matches) {
    ITEM_H = 60;
  }

  var stripS  = document.getElementById('hh-strip-s');
  var stripO  = document.getElementById('hh-strip-o');
  var stripH  = document.getElementById('hh-strip-h');
  var saveVal = document.getElementById('hh-save-val');
  var spinBtn = document.getElementById('hh-spin-btn');

  function build(el, key, cls) {
    var parts = [];
    for (var r = 0; r < REPEAT + 1; r++) {
      for (var i = 0; i < data.length; i++) {
        parts.push('<div class="hh-item ' + cls + '">' + fmt(data[i][key]) + '</div>');
      }
    }
    el.innerHTML = parts.join('');
  }
  build(stripS, 's', '');
  build(stripO, 'o', 'hh-item-other');
  build(stripH, 'h', 'hh-item-ours');

  var currentIdx = 0;
  var spinning = false;

  function setPos(el, pos, trans) {
    el.style.transition = trans || '';
    el.style.transform = 'translateY(' + (-pos * ITEM_H) + 'px)';
  }
  setPos(stripS, 0, 'none');
  setPos(stripO, 0, 'none');
  setPos(stripH, 0, 'none');

  function spin(targetIdx) {
    if (spinning || targetIdx === currentIdx) return;
    spinning = true;
    spinBtn.disabled = true;

    setPos(stripS, currentIdx, 'none');
    setPos(stripO, currentIdx, 'none');
    setPos(stripH, currentIdx, 'none');
    void stripS.offsetHeight;

    var d1 = 2400, d2 = 2800, d3 = 3200;
    var ease = 'cubic-bezier(0.17, 0.67, 0.21, 0.99)';
    var finalPos = REPEAT * data.length + targetIdx;
    setPos(stripS, finalPos, 'transform ' + d1 + 'ms ' + ease);
    setPos(stripO, finalPos, 'transform ' + d2 + 'ms ' + ease);
    setPos(stripH, finalPos, 'transform ' + d3 + 'ms ' + ease);

    var startSave = data[currentIdx].save;
    var endSave   = data[targetIdx].save;
    var start     = performance.now();

    function tick(now) {
      var t = Math.min((now - start) / d3, 1);
      if (t < 0.88) {
        var rnd = data[Math.floor(Math.random() * data.length)].save;
        saveVal.textContent = fmt(rnd);
      } else {
        var localT = (t - 0.88) / 0.12;
        var eased = 1 - Math.pow(1 - localT, 3);
        saveVal.textContent = fmt(Math.round(startSave + (endSave - startSave) * eased));
      }
      if (t < 1) requestAnimationFrame(tick);
      else saveVal.textContent = fmt(endSave);
    }
    requestAnimationFrame(tick);

    setTimeout(function() {
      setPos(stripS, targetIdx, 'none');
      setPos(stripO, targetIdx, 'none');
      setPos(stripH, targetIdx, 'none');
      void stripS.offsetHeight;
      currentIdx = targetIdx;
      spinning = false;
      spinBtn.disabled = false;
    }, d3 + 80);
  }

  spinBtn.addEventListener('click', function() {
    var next;
    do { next = Math.floor(Math.random() * data.length); } while (next === currentIdx);
    spin(next);
  });

  var btns = document.querySelectorAll('[data-hh-idx]');
  for (var i = 0; i < btns.length; i++) {
    (function(b) {
      b.addEventListener('click', function() { spin(parseInt(b.dataset.hhIdx, 10)); });
    })(btns[i]);
  }

  // Rebuild on resize if crossing the mobile breakpoint
  var wasMobile = ITEM_H === 60;
  window.addEventListener('resize', function() {
    var isMobile = window.matchMedia('(max-width: 560px)').matches;
    if (isMobile !== wasMobile) {
      ITEM_H = isMobile ? 60 : 72;
      wasMobile = isMobile;
      setPos(stripS, currentIdx, 'none');
      setPos(stripO, currentIdx, 'none');
      setPos(stripH, currentIdx, 'none');
    }
  });
})();
</script> </div> </div> <div class="elementor-element elementor-element-c58cd1d e-flex e-con-boxed e-con e-parent nitro-offscreen e-lazyloaded" data-id="c58cd1d" data-element_type="container" data-e-type="container"> <div class="e-con-inner"> <div class="elementor-element elementor-element-917ed04 e-con-full e-flex e-con e-child" data-id="917ed04" data-element_type="container" data-e-type="container"> <div class="elementor-element elementor-element-1a19163 elementor-widget elementor-widget-image" data-id="1a19163" data-element_type="widget" data-e-type="widget" data-widget_type="image.default"> <img width="562" height="17" alt="" sizes="(max-width: 562px) 85vw, 562px" nitro-lazy-srcset="<?php echo $mbn_lp_assets_url; ?>img-separator-7549c0e2.png 562w, <?php echo $mbn_lp_assets_url; ?>img-separator-300x9-492269c8.png 300w" nitro-lazy-src="<?php echo $mbn_lp_assets_url; ?>img-separator-7549c0e2.png" class="attachment-large size-large wp-image-8890 lazyloaded" decoding="async" nitro-lazy-empty="" id="OTI0OjQzNA==-1" data-nitro-empty-id="OTI0OjQzNA==-1" src="<?php echo $mbn_lp_assets_url; ?>img-separator-7549c0e2.png" srcset="<?php echo $mbn_lp_assets_url; ?>img-separator-7549c0e2.png 562w, <?php echo $mbn_lp_assets_url; ?>img-separator-300x9-492269c8.png 300w"> </div> <div class="elementor-element elementor-element-9be674c elementor-widget elementor-widget-heading" data-id="9be674c" data-element_type="widget" data-e-type="widget" data-widget_type="heading.default"> <h2 class="elementor-heading-title elementor-size-default">We only get paid when we get you paid</h2> </div> <div class="elementor-element elementor-element-cd8135d elementor-widget elementor-widget-text-editor" data-id="cd8135d" data-element_type="widget" data-e-type="widget" data-widget_type="text-editor.default"> <p>When you are hurt, the last thing you need is a lawyer learning the Phoenix court system on your dime.</p><p>You need a firm that knows the judges, knows the process, knows how these cases work in the Valley, and knows how to fight to get you every dollar you deserve.</p><p>At Hastings &amp; Hastings, we have been representing injury victims in Phoenix and across the Valley for nearly 50 years. That kind of experience is earned, not claimed. It is earned, case by case, over decades.</p><p>Our team of experienced personal injury and wrongful death attorneys brings more than 90 years of combined legal experience to every case. And we have one mission: to help you keep more of the settlement you deserve. That is why we reduced our fee, so more money goes into your pocket.</p> </div> </div> <div class="elementor-element elementor-element-1a10998 e-con-full e-flex e-con e-child" data-id="1a10998" data-element_type="container" data-e-type="container"> <div class="elementor-element elementor-element-ca0f081 elementor-widget elementor-widget-image" data-id="ca0f081" data-element_type="widget" data-e-type="widget" data-widget_type="image.default"> <img width="550" height="541" alt="" sizes="(max-width: 550px) 85vw, 550px" nitro-lazy-srcset="<?php echo $mbn_lp_assets_url; ?>hastings-md-bc9cbe59.jpg 550w, <?php echo $mbn_lp_assets_url; ?>hastings-md-300x295-4eb17b60.jpg 300w" nitro-lazy-src="<?php echo $mbn_lp_assets_url; ?>hastings-md-bc9cbe59.jpg" class="attachment-large size-large wp-image-9552 lazyloaded" decoding="async" nitro-lazy-empty="" id="OTMyOjQ0Ng==-1" data-nitro-empty-id="OTMyOjQ0Ng==-1" src="<?php echo $mbn_lp_assets_url; ?>hastings-md-bc9cbe59.jpg" srcset="<?php echo $mbn_lp_assets_url; ?>hastings-md-bc9cbe59.jpg 550w, <?php echo $mbn_lp_assets_url; ?>hastings-md-300x295-4eb17b60.jpg 300w"> </div> </div> </div> </div> <div class="elementor-element elementor-element-dd43eab e-flex e-con-boxed e-con e-parent nitro-offscreen e-lazyloaded" data-id="dd43eab" data-element_type="container" data-e-type="container"> <div class="e-con-inner"> <div class="elementor-element elementor-element-965b083 e-con-full e-flex e-con e-child" data-id="965b083" data-elemen