  if (window.jQuery && window.jQuery.fn && window.jQuery.fn.slick) {
    init();
  } else {
    var tries = 0;
    var iv = setInterval(function() {
      tries++;
      if (window.jQuery && window.jQuery.fn && window.jQuery.fn.slick) {
        clearInterval(iv);
        init();
      } else if (tries > 150) {
        clearInterval(iv);
        init();
      }
    }, 100);
  }
})();
</script></body></html>